waves.point_eqs_eel:
repeats=10;
samplerepeat=sample*repeats;
cycle=int(samplerepeat);
sampcyc=samplerepeat - cycle;
cycleto1=cycle/repeats;

n=sampcyc*6.283;
phs=sampcyc;
tm=q1+phs+(cycleto1)*0.1;
tmm=time;
rsample=(1-sampcyc*0.9)*2.2*(cycleto1+1);
a=sampcyc * below(sampcyc,0.95);
a=a*a;

//waving
tmc=tm+cycle-phs*0.2;
variation=sin(cycleto1*6.283)*9;
swap=above(sample,0.5)*2-1;
wavex=sin(tmc*(19+variation)*swap)*rsample*0.04;
wavey=cos(tmc*(19+variation)*swap)*rsample*0.04;

xp=sin(tm)*0.4 ;
yp=cos(tm)*0.4 ;

xp=xp*sin(tm*3);
yp=yp*cos(tm*2.6);

xp=xp*sin(tm*0.43);
yp=yp*(cos(tm*1.79)*0.5+0.5);

xp=xp+wavex;
yp=yp+wavey;

x=xp+0.5;
y=yp*1.333 + 0.5;


trailsize=0.85;
head=above(a,trailsize);
tail=1-head;
r=1*head + 0.5*tail;
g=0.8*head + 0.3*tail;
b=0.5*head;

a=a*0.25

